SELECT T_A.* , CRYPTO_DEC('normal', T_A.NAME_ENC, '', 0) AS NAME , CRYPTO_DEC('normal', T_A.TELEPHONE_NUMBER_ENC, '', 0) AS TELEPHONE_NUMBER , CRYPTO_DEC('normal', T_A.ADDRESS_ENC, '', 0) AS ADDRESS , CRYPTO_DEC('normal', T_A.ADDRESS_DETAIL_ENC, '', 0) AS ADDRESS_DETAIL FROM ( SELECT SHIPMENT_RETURN_ID , SELLER_ID , ADDRESS_NAME , NAME AS NAME_ENC , TELEPHONE_NUMBER AS TELEPHONE_NUMBER_ENC , ZIPCODE , ADDRESS AS ADDRESS_ENC , ADDRESS_DETAIL AS ADDRESS_DETAIL_ENC , DEFAULT_ADDRESS_FLAG , CREATED_DATE FROM OP_SHIPMENT_RETURN
WHERE SELLER_ID = #{value}
ORDER BY SHIPMENT_RETURN_ID DESC ) T_A

SELECT T_A.* , CRYPTO_DEC('normal', T_A.NAME_ENC, '', 0) AS NAME , CRYPTO_DEC('normal', T_A.TELEPHONE_NUMBER_ENC, '', 0) AS TELEPHONE_NUMBER , CRYPTO_DEC('normal', T_A.ADDRESS_ENC, '', 0) AS ADDRESS , CRYPTO_DEC('normal', T_A.ADDRESS_DETAIL_ENC, '', 0) AS ADDRESS_DETAIL FROM ( SELECT SHIPMENT_RETURN_ID , SELLER_ID , ADDRESS_NAME , NAME AS NAME_ENC , TELEPHONE_NUMBER AS TELEPHONE_NUMBER_ENC , ZIPCODE , ADDRESS AS ADDRESS_ENC , ADDRESS_DETAIL AS ADDRESS_DETAIL_ENC , DEFAULT_ADDRESS_FLAG , CREATED_DATE FROM OP_SHIPMENT_RETURN
AND SELLER_ID = #{sellerId}
AND DEFAULT_ADDRESS_FLAG = #{defaultAddressFlag}
AND SHIPMENT_RETURN_ID = ( CASE WHEN (SELECT SHIPMENT_RETURN_ID FROM OP_ITEM WHERE ITEM_ID = #{itemId}
AND DEFAULT_ADDRESS_FLAG = #{defaultAddressFlag}
ORDER BY SHIPMENT_RETURN_ID DESC LIMIT 1) IS NULL THEN
(SELECT SHIPMENT_RETURN_ID FROM OP_SHIPMENT_RETURN WHERE SELLER_ID = #{sellerId}
AND DEFAULT_ADDRESS_FLAG = #{defaultAddressFlag}
ORDER BY SHIPMENT_RETURN_ID DESC LIMIT 1) ELSE (SELECT SHIPMENT_RETURN_ID FROM OP_ITEM WHERE ITEM_ID = #{itemId}
AND DEFAULT_ADDRESS_FLAG = #{defaultAddressFlag}
ORDER BY SHIPMENT_RETURN_ID DESC LIMIT 1) END )
AND SHIPMENT_RETURN_ID = #{shipmentReturnId}
ORDER BY SHIPMENT_RETURN_ID DESC LIMIT 1 ) T_A

mapper.update:
UPDATE OP_SHIPMENT_RETURN SET
	DEFAULT_ADDRESS_FLAG = 'N'
WHERE SHIPMENT_RETURN_ID != #{shipmentReturnId} AND SELLER_ID = #{sellerId}
